	LIEF_BELEG_POS_ID NUMBER(38,0) NOT NULL COMMENT 'Das Feld enthält die Nummer einer Lieferscheinposition und dient zusammen mit der Lieferscheinbeleg ID der eindeutigen Identifikation der Lieferscheinbelegpositionen.',
	HANDLING_UNIT_ID NUMBER(38,0) NOT NULL COMMENT 'Interne Handling Unit_1 Nummer.',
	HANDLING_UNIT_POS_ID NUMBER(38,0) NOT NULL COMMENT 'Handling Unit_1 Position.',
	HU_TYP_ID NUMBER(38,0) NOT NULL COMMENT 'Der Typ des Handling Unit_1 Positionsinhalts 1 ist immer die Ware, damit kann man Ladungsträger und Ladehilfsmittel ausschließen.',
	BEST_BELEG_ID NUMBER(38,0) NOT NULL COMMENT 'Das Feld enthält die Beleg ID der Bestellung und dient der eindeutigen Identifikation der Bestellbelege.',
	TRANSPORTATION_UNIT_ID NUMBER(38,0) NOT NULL COMMENT 'Transporteinheit (intern).',
	BELOS_VORGANG_ID NUMBER(38,0) NOT NULL COMMENT 'Referenz zum Belos-Vorgang. Nicht in jedem Fall vorhanden. Defaultwert ist 0.',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_1 ID wird verwendet für Beziehung Lager zu Verteilzentrum.',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer.',
	LAGERNUMMER_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Lagernummer / Lagerkomplex.',
	VERSANDSTELLE_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Ort, an dem Lieferungen bearbeitet werden. Es kann sich dabei um einen physischen Ort (z.B. ein Lager oder eine_1 Gruppe_1 von Laderampen) oder um eine_1 logische Gruppierung (z.B. eine_1 Gruppe_1 von Personen, die für die Versandaktivitäten zuständig ist) handeln.',
	LAGERORT_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Schlüssel für die Lagerorte. Die Lagerorte sind pro Werk / Betrieb eindeutig. Aus lgort.',
	LAGERSORTIMENT_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Lagersortiment ID.',
	DIFF_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Wenn eine_1 Lieferposition nicht vollständig beliefert werden kann, wird die Restmenge vom VZ nachgeliefert oder muss vom Markt neu bestellt werden. Diese Information wird auch als Nachlieferkennzeichen bezeichnet.',
	DAT_LIEF_SOLL DATE NOT NULL COMMENT 'Lieferdatum der Position.',
	LIEF_TYP_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Klassifikation, mit der zwischen verschiedenen Arten der Lieferung unterschieden wird. Die Lieferart bestimmt, wie das System eine_1 Lieferung bearbeitet.',
	VERTR_BELEG_TYP_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Dieses Kennzeichen liefert die Information aus welchem Vorgang dieser Vertriebsbeleg generiert wurde, z. B. wurde der Lieferschein aufgrund eines Wareneingangs generiert.',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Artikelnummer.',
	KUNDE_ID NUMBER(38,0) NOT NULL COMMENT 'Die Kunde ID ist die wup_id des belieferten Marktes. Dazu gibt es auch eine_1 mandant_id_kunde.',
	WG_VERKETT_LIEF NUMBER(38,0) NOT NULL COMMENT 'Die Warengruppenverkettung gibt an, welche Artikel_1 gemeinsam auf eine_1 Palette gepackt werden.',
	MENGE_LIEF_SOLL_KOLLI NUMBER(18,3) COMMENT 'Die Soll-Liefermenge dient dazu, die ursprüngliche Liefermenge einer Aus- oder Anlieferung festzuhalten. Sie bezieht sich auf die Mengeneinheit der Liefermenge (LFIMG). Es handelt sich hier um Kolli!  ',
	MENGE_LIEF_IST_KOLLI NUMBER(18,3) COMMENT 'Ist-Liefermenge in Kolli.',
	MENGE_LIEF_SOLL_BME NUMBER(18,3) COMMENT 'Die Soll-Liefermenge dient dazu, die ursprüngliche Liefermenge einer Aus- oder Anlieferung festzuhalten. Sie ist berechnet (redundante Speicherung) und in Bestellmengeneinheit dargestellt.',
	MENGE_LIEF_IST_BME NUMBER(18,3) COMMENT 'Ist-Liefermenge der Lieferposition, ausgedrückt in Bestellmengeneinheit aus lfimg.',
	MENGE_LIEF_SOLL_PAL NUMBER(18,3) COMMENT 'Soll-Liefermenge in Paletten.',
	MENGE_LIEF_IST_PAL NUMBER(18,3) COMMENT 'Ist-Liefermenge in Paletten.',
	LIEF_PAL_TYP_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Der Palettentyp einer Lieferung kennzeichnet, ob es sich um eine_1 Ganzpalettenlieferung, Mischpalettenlieferung, Lieferung je Markt, etc., handelt.',
	LIEF_PAL_TYP_DWH_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Abgeleiteter Palettentyp (6 wird in 61 und 64 unterteilt),',
	MANDANT_ID_KUNDE NUMBER(38,0) NOT NULL COMMENT 'Der Kunde kann zu einem anderen Mandanten als dem der wup_id gehören, z.B. wenn ein Lager aus CZ einen Markt in SK beliefert.',
	WERBEWARE_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Aus besch_lief_1: Wird gefüllt, wenn die Bestellart eine_1 Werbebestellart ist. Wertevorrat: W = Werbung, N = Normalware, B = Beides W und N, S = Schnellschuss.',
	BESTELLART_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Durch die Einkaufsbelegart kann man z.B. zwischen einer Bestellung, einer Anfrage und einem Lieferplan unterscheiden.',
	HU_STATUS_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Bewegungsstatus der Handling Unit.',
	HANDLING_UNIT_ID_EXT_PARENT VARCHAR(20) COLLATE 'en-ci' COMMENT 'Externe Handling Unit_1 Identifikation aus exidv. Nummer der Versandeinheit (NVE) PARENT.',
	HANDLING_UNIT_ID_EXT VARCHAR(20) COLLATE 'en-ci' COMMENT 'Externe Handling Unit_1 Identifikation aus exidv. Nummer der Versandeinheit (NVE).',
	HANDLING_UNIT_ID_PARENT NUMBER(18,0) COMMENT 'Übergeordnete Handling Unit.',
	ORIGINALPOSITION_LIEF_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Kennzeichen Orginalposition.',
	POSITION_CHARG_SPLIT_FG NUMBER(38,0) COMMENT 'Position mit Chargensplit.',
	DISPONENT_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Disponent ID.',
	DAT_HALTBARKEIT DATE COMMENT 'Dieses Feld enthält das Mindesthaltbarkeitsdatum.',
	CHARGE_ID VARCHAR(10) COLLATE 'en-ci' COMMENT 'Charge ID.',
	ANZAHL_PACKSTUECK NUMBER(38,0) COMMENT 'Anzahl von Packstücken.',
	VK_NETTO_LIEF_IST NUMBER(18,4) COMMENT 'Ist-Liefermenge, bewertet mit dem Verkaufspreis, minus Mehrwertsteuer. Redundant abgelegt zur Performancesteigerung.',
	VK_NETTO_LIEF_SOLL NUMBER(18,4) COMMENT 'Soll-Liefermenge, bewertet mit dem Verkaufspreis, minus Mehrwertsteuer. Redundant abgelegt zur Performancesteigerung.',
	TRANSPORTSORTIMENT_ID VARCHAR(2) COLLATE 'en-ci' COMMENT 'Transportsortiment ID - concatenation of  Lagersortiment IDs that should be put on the same truck for transportation (for example 27 means Lagersortiment ID 2 and Lagersortiment ID 7 are transported together)',
	SPLIT_LIEF_KENNZ VARCHAR(1) COMMENT 'Kennzeichen Split-Lieferung: leer = keine Splitlieferung, O = Orginalposition, S = Split-Position.',
	LIEF_BELEG_ID_ORIG NUMBER(18,0) COMMENT 'Orginal-Lieferbeleg zu Split-Lieferpositionen.',
	WG_VERKETT_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag. Zeigt an, ob eine_1 Warengruppenverkettung existiert. Aus dem Feld zzlvwgrvkhier_kz.',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Währung, z.B. CZK, EUR.',
	UEBG_CHARGENSPLIT_POS NUMBER(38,0) COMMENT 'Übergeordnete Position der Chargensplitposition.',
	AUSLIEFERUNGSGRUPPE_ID VARCHAR(4) COMMENT 'Auslieferungsgruppe aus ZLF_AUSLFEL.',
	DAT_ERSTELLUNG DATE COMMENT 'Erstellungsdatum des Lieferbeleges - Quelle: LIKP.ERDAT.',
	TMS_TOUR_ID NUMBER(38,0) COMMENT 'ID des Tours (Tournummer). Eine_1 Tour_1 kann an mehr als einem Datum stattfinden, daher ist die Spalte tms_tour_id allein nicht eindeutig. Aus pltop.tonr',
	DAT_TOUR DATE COMMENT 'Tourdatum',
	TMS_SYSTEM_ID NUMBER(38,0) COMMENT 'Spezifiziert das Quellsystem, aus dem die Daten kommen.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_BESCH_LIEF_WA_DET primary key (MANDANT_ID, LIEF_BELEG_ID, LIEF_BELEG_POS_ID, HANDLING_UNIT_ID, HANDLING_UNIT_POS_ID, BEST_BELEG_ID)
)COMMENT='LIS-LOG - Frontend Data Mart. Warenausgangs-Positionen (Zusammenführung Lieferung + Bestellung + Handling Unit_1).'
